export type Messages = (typeof catalogs)["en"];
const aliases: Record<string, string> = { in: "id", iw: "he", ji: "yi", no: "nb", tl: "fil" };
function canonical(locale: string): string[] {
  try {
    const tag = Intl.getCanonicalLocales(locale.replaceAll("_", "-"))[0] ?? "";
    const singleton = tag.search(/-[a-zA-Z0-9]-/);
    return (singleton < 0 ? tag : tag.slice(0, singleton)).split("-");
  } catch {
    return [];
  }
}
/**
 * The closest shipped catalog for a BCP 47 tag, else the base locale. Legacy codes map to their
 * successors, Chinese infers its script from the region, and Portuguese outside Brazil reads pt-PT.
 */
export function messages(locale?: string): Messages {
  const [first, ...subtags] = locale ? canonical(locale) : [];
  if (first) {
    const language = aliases[first] ?? first;
    const region = subtags.find((subtag) => /^([A-Z]{2}|[0-9]{3})$/.test(subtag));
    const script =
      subtags.find((subtag) => /^[A-Z][a-z]{3}$/.test(subtag)) ??
      (language === "zh" ? (region && ["HK", "MO", "TW"].includes(region) ? "Hant" : "Hans") : undefined);
    const candidates = [
      [language, script, region],
      [language, script],
      [language, region],
      [language],
      [language, language === "pt" ? (region === undefined ? "BR" : "PT") : undefined],
    ];
    for (const parts of candidates) {
      if (parts.includes(undefined)) continue;
      const tag = parts.join("-");
      if (tag in catalogs) return catalogs[tag as keyof typeof catalogs];
    }
  }
  return catalogs["en"];
}
